 1	method BitwiseXOR(a: seq<bv32>, b: seq<bv32>) returns (result: seq<bv32>)
 2	    requires |a| == |b|
 3	    ensures |result| == |a|
 4	    ensures forall i :: 0 <= i < |result| ==> result[i] == a[i] ^ b[i]
 5	{
 6	    result := [];
 7	    var i := 0;
 8	    while i < |a|
 9	        invariant |result| == i
10	        invariant forall k :: 0 <= k < i ==> result[k] == a[k] ^ b[k]
11	    {
12	        result := result + [a[i] ^ b[i]];
13	        i := i + 1;
14	    }
15	}

